		@Override
		protected Long getNextElement() {
			try {
				RunRecord exact = peekExact();
				RunRecord wildcard = wildcardPosition < wildcardEnd ? owner.readRecord(wildcardPosition) : null;
				if (exact == null && wildcard == null) {
					return null;
				}
				if (wildcard == null || exact != null && exact.rowHandle <= wildcard.rowHandle) {
					pendingExact = null;
					return exact.rowHandle;
				}
				wildcardPosition++;
				return wildcard.rowHandle;
			} catch (IOException failure) {
				Throwable terminalFailure = owner.failFromCursor(
						new BindingSetReplayException("Unable to read the local binding-set replay index", failure));
				if (terminalFailure instanceof RuntimeException exception) {
					throw exception;
				}
				if (terminalFailure instanceof Error error) {
					throw error;
				}
				throw new BindingSetReplayException("Unable to read the local binding-set replay index",
						terminalFailure);
			}
		}

		private RunRecord peekExact() throws IOException {
			if (pendingExact != null) {
				return pendingExact;
			}
			while (exactPosition < exactEnd) {
				RunRecord exact = owner.readRecord(exactPosition++);
				if (exact == null) {
					return null;
				}
				if (exact.kind == COMPLETE && exact.hash == expectedHash) {
					pendingExact = exact;
					return pendingExact;
				}
			}
			return null;
		}

		@Override
		protected void handleClose() {
			owner.unregister(this);
		}

		private Throwable closeInternal() {
			try {
				close();
				return null;
			} catch (Throwable failure) {
				return failure;
			}
		}
